/* 开屏变身动画已于 v4 移除；保留 audioCtx 供跟读功能的音量表使用 */
var AC=null;
function audioCtx(){
  var C=window.AudioContext||window.webkitAudioContext;
  if(!C) return null;
  if(!AC) AC=new C();
  if(AC.state==="suspended"){ try{AC.resume();}catch(e){} }
  return AC;
}
